function caUnitsBuild(){for(const k in CA_U)delete CA_U[k];
  CA_CATS.forEach(cat=>CA_UD[cat].u.forEach(r=>{const u: CaUnit={id:r[0],sym:r[1],f:r[2]!,ex:!!r[3],nm:r[4],off:r[5]||0,cat};CA_U[cat+":"+u.id]=u;if(!CA_U[u.id])CA_U[u.id]=u}));
  (caSt().units||[]).forEach(c=>{if(!CA_UD[c.cat]||!(c.f!>0))return;const u: CaUnit={id:"x_"+c.id,sym:c.sym,f:c.f!,ex:false,nm:c.name+"|"+c.name+"|"+c.name+"|"+c.name,off:0,cat:c.cat,custom:true};CA_U[c.cat+":"+u.id]=u;if(!CA_U[u.id])CA_U[u.id]=u})}
const caUnitsOf=(cat: string)=>{const out=CA_UD[cat].u.map(r=>CA_U[cat+":"+r[0]]);(caSt().units||[]).forEach(c=>{const u=CA_U[c.cat+":x_"+c.id];if(c.cat===cat&&u)out.push(u)});return out};
