const CA_UPRI=["length","mass","time","volume","temp","area","speed","pressure","energy","power","force","freq","angle","data","rate","current","voltage","resist","capac","induct","magnet","density","flow","accel","torque","molconc","massconc","amount","molmass","dose","eqdose","activity","dtemp","fuel"];
function caUnitFind(s: string | undefined){s=String(s||"").trim();if(!s)return null;if(CA_U[s]&&s.includes(":"))return CA_U[s];
  for(const cat of CA_UPRI){const hit=caUnitsOf(cat).find(u=>u.id===s||u.sym===s);if(hit)return hit}
  const low=s.toLowerCase();for(const cat of CA_UPRI){const hit=caUnitsOf(cat).find(u=>u.sym.toLowerCase()===low||u.id.toLowerCase()===low);if(hit)return hit}return null}
/* conversion through the canonical unit */
function caToBase(v: number,u: CaUnit){if(u.cat==="fuel"){if(v<=0)throw new CaErr("ca_ePos");return CA_FUEL[u.id]?CA_FUEL[u.id][0](v):v}return v*u.f+(u.off||0)}
function caFromBase(b: number,u: CaUnit){if(u.cat==="fuel"){if(b<=0)throw new CaErr("ca_ePos");return CA_FUEL[u.id]?CA_FUEL[u.id][1](b):b}return (b-(u.off||0))/u.f}
function caConvert(v: number,from: CaUnit,to: CaUnit){if(from.cat!==to.cat)throw new CaErr("ca_eDim");if(from.cat==="temp"&&caToBase(v,from)<0)throw new CaErr("ca_eAbsZero");return caFromBase(caToBase(v,from),to)}
/* quantities in expressions: {q:1,v:value in base,cat,u:display unit id} */
function caQ(v: number,u: CaUnit): CaV{if(u.cat==="fuel")throw new CaErr("ca_eFuelExpr");return {q:1,v:caToBase(v,u),cat:u.cat,u:u.id,aff:!!CA_UD[u.cat].aff} as unknown as CaV}
function caQScale(a: CaV,k: number){if(a.aff)throw new CaErr("ca_eAffine");return Object.assign({},a,{v:a.v!*k})}
function caQBin(op: string,a: CaV,b: CaV,p: number){const qa=a&&a.q,qb=b&&b.q;
  if(op==="+"||op==="-"){if(!qa||!qb)throw new CaErr("ca_eDimMix",p);if(a.cat!==b.cat)throw new CaErr("ca_eDim",p,caCatName(a.cat!)+" / "+caCatName(b.cat!));if(a.aff||b.aff)throw new CaErr("ca_eAffine",p);return Object.assign({},a,{v:op==="+"?a.v!+b.v!:a.v!-b.v!})}
  if(op==="*"){if(qa&&qb)throw new CaErr("ca_eDimProd",p);return qa?caQScale(a,b):caQScale(b,a)}
  if(op==="/"){if(qa&&qb){if(a.cat!==b.cat)throw new CaErr("ca_eDimProd",p);if(b.v===0)throw new CaErr("ca_eDiv0",p);if(a.aff||b.aff)throw new CaErr("ca_eAffine",p);return a.v!/b.v!}if(qb)throw new CaErr("ca_eDimProd",p);if(b===0)throw new CaErr("ca_eDiv0",p);return caQScale(a,1/b)}
  throw new CaErr("ca_eDimProd",p)}
function caQVal(q: CaV){const u=CA_U[q.cat+":"+q.u]||CA_U[q.u!];return caFromBase(q.v!,u)}
function caFmtQ(q: CaV,o: CaFmtOpts={}): string{const u=CA_U[q.cat+":"+q.u]||CA_U[q.u!];return caFmt(caFromBase(q.v!,u),o)+(o.plain?" ":" ")+u.sym}

