    const conv=(s: number[])=>{const t=s.filter(isFinite).slice(-4);if(t.length<3)return null;const d1=Math.abs(t[t.length-1]-t[t.length-2]),d0=Math.abs(t[1]-t[0]);return d1<=1e-6*Math.max(1,Math.abs(t[t.length-1]))&&d1<=d0+1e-12?t[t.length-1]:null};
