function caTriSvg(a: number,b: number,c: number,A: number,B: number,C: number){/* place C at origin, B on x axis */const W=260,H=170;const bx=a,cx=b*Math.cos(C),cy=b*Math.sin(C);const xs=[0,bx,cx],ys=[0,0,cy];const mnx=Math.min(...xs),mxx=Math.max(...xs),mxy=Math.max(...ys)||1;const k=Math.min((W-50)/(mxx-mnx||1),(H-40)/mxy);
  const P=(x: number,y: number)=>[25+(x-mnx)*k,H-20-y*k];const [p1,p2,p3]=[P(0,0),P(bx,0),P(cx,cy)];const mid=(u: number[],v: number[])=>[(u[0]+v[0])/2,(u[1]+v[1])/2];
  return `<svg class="ca-dia" viewBox="0 0 ${W} ${H}" role="img" aria-label="triangle" direction="ltr"><polygon points="${[p1,p2,p3].map(p=>p.join(",")).join(" ")}" class="sh"/><text x="${p1[0]-12}" y="${p1[1]+4}">C</text><text x="${p2[0]+5}" y="${p2[1]+4}">B</text><text x="${p3[0]}" y="${p3[1]-6}" text-anchor="middle">A</text>
    <text x="${mid(p1,p2)[0]}" y="${mid(p1,p2)[1]+14}" text-anchor="middle" class="lb">a</text><text x="${mid(p1,p3)[0]-8}" y="${mid(p1,p3)[1]}" text-anchor="end" class="lb">b</text><text x="${mid(p2,p3)[0]+8}" y="${mid(p2,p3)[1]}" class="lb">c</text></svg>`}
