function caGrFns(){const G=caGrState();return G.f.map((s,i)=>{if(!String(s).trim())return null;try{return {i,f:caMkFn(s),s}}catch(e){return {i,err:caErrMsg(e),s}}})}
function caGrDraw(){const R=caRoot();const svg=R?.querySelector<HTMLInputElement>("[data-grsvg]");if(!svg)return;const G=caGrState();const W=svg.clientWidth||600,H=svg.clientHeight||380;svg.setAttribute("viewBox",`0 0 ${W} ${H}`);const fns=caGrFns();
  const X=(x: number)=>(x-G.x0)/(G.x1-G.x0)*W,Y=(y: number)=>H-(y-G.y0)/(G.y1-G.y0)*H;const nice=(span: number,n: number)=>{const r=span/n;const p=Math.pow(10,Math.floor(Math.log10(r)));const m=r/p;return (m<1.5?1:m<3?2:m<7?5:10)*p};
  const sx=nice(G.x1-G.x0,8),sy=nice(G.y1-G.y0,6);let g="";for(let x=Math.ceil(G.x0/sx)*sx;x<=G.x1;x+=sx){const px=X(x);g+=`<line x1="${px}" x2="${px}" y1="0" y2="${H}" class="g${Math.abs(x)<sx/2?" ax":""}"/><text x="${px+3}" y="${Math.min(H-4,Math.max(12,Y(0)+12))}">${caE(caFmt(Math.abs(x)<sx/1e6?0:x,{sig:4}))}</text>`}
  for(let y=Math.ceil(G.y0/sy)*sy;y<=G.y1;y+=sy){const py=Y(y);g+=`<line y1="${py}" y2="${py}" x1="0" x2="${W}" class="g${Math.abs(y)<sy/2?" ax":""}"/>${Math.abs(y)<sy/1e6?"":`<text x="${Math.min(W-30,Math.max(3,X(0)+4))}" y="${py-3}">${caE(caFmt(y,{sig:4}))}</text>`}`}
  let paths="";const info: string[]=[];fns.forEach(fn=>{if(!fn)return;if(fn.err){info.push(`<p class="bad">f${fn.i+1} : ${caE(fn.err)}</p>`);return}const N=Math.max(200,Math.min(1600,W*2));let d="",pen=false,py=null;for(let k=0;k<=N;k++){const x=G.x0+(G.x1-G.x0)*k/N;const y=fn.f!(x);if(!isFinite(y)){pen=false;continue}const yy=Y(y);if(pen&&py!==null&&Math.abs(yy-py)>H*3){pen=false}
      if(yy<-H*4||yy>H*5){pen=false;py=yy;continue}d+=(pen?"L":"M")+X(x).toFixed(1)+" "+yy.toFixed(1);pen=true;py=yy}paths+=`<path d="${d}" class="s${fn.i}" fill="none"/>`;
    const rs=caRoots(fn.f!,G.x0,G.x1,800).slice(0,6);if(rs.length)info.push(`<p><b class="s${fn.i}">f${fn.i+1}</b> = 0 : x ≈ ${rs.map(r=>caFmt(r,{sig:6})).join(" ; ")}</p>`)});
  svg.innerHTML=`<g class="grid">${g}</g>${paths}<line class="cur" data-grcur x1="-10" x2="-10" y1="0" y2="${H}"/>`;R!.querySelector<HTMLInputElement>("[data-grinfo]")!.innerHTML=info.join("")||`<p class="ca-mut sm">${L4("Les zéros visibles s’affichent ici.|Visible zeros are listed here.|Sichtbare Nullstellen erscheinen hier.|تظهر الأصفار المرئية هنا.")}</p>`;
  caSt().graph=G;caSave()}
function caGrFit(){const G=caGrState();const fns=caGrFns().filter(f=>f&&f.f);let lo=Infinity,hi=-Infinity;fns.forEach(fn=>{for(let k=0;k<=400;k++){const y=fn!.f!(G.x0+(G.x1-G.x0)*k/400);if(isFinite(y)){lo=Math.min(lo,y);hi=Math.max(hi,y)}}});if(!isFinite(lo))return;if(lo===hi){lo-=1;hi+=1}const m=(hi-lo)*.08;G.y0=lo-m;G.y1=hi+m}
function caGrMount(){const R=caRoot();const svg=R!.querySelector<HTMLInputElement>("[data-grsvg]");caGrDraw();const G=caGrState();let drag: { x: number; y: number; g: CaGr } | null=null;
  const pt=(e: MouseEvent)=>{const r=svg!.getBoundingClientRect();return [(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]};
  svg!.addEventListener("wheel",e=>{e.preventDefault();const [fx,fy]=pt(e);const k=e.deltaY>0?1.15:1/1.15;const cx=G.x0+fx*(G.x1-G.x0),cy=G.y1-fy*(G.y1-G.y0);G.x0=cx-(cx-G.x0)*k;G.x1=cx+(G.x1-cx)*k;G.y0=cy-(cy-G.y0)*k;G.y1=cy+(G.y1-cy)*k;caGrSyncW();caGrDraw()},{passive:false});
  svg!.addEventListener("pointerdown",e=>{drag={x:e.clientX,y:e.clientY,g:{...G}};svg!.setPointerCapture(e.pointerId);svg!.classList.add("drag")});
  svg!.addEventListener("pointermove",e=>{const r=svg!.getBoundingClientRect();if(drag){const dx=(e.clientX-drag.x)/r.width*(drag.g.x1-drag.g.x0),dy=(e.clientY-drag.y)/r.height*(drag.g.y1-drag.g.y0);G.x0=drag.g.x0-dx;G.x1=drag.g.x1-dx;G.y0=drag.g.y0+dy;G.y1=drag.g.y1+dy;caGrSyncW();caGrDraw();return}
    const [fx]=pt(e);const x=G.x0+fx*(G.x1-G.x0);const tip=R!.querySelector<HTMLInputElement>("[data-grtip]");const cur=svg!.querySelector<HTMLInputElement>("[data-grcur]");cur?.setAttribute("x1",(fx*r.width) as unknown as string);cur?.setAttribute("x2",(fx*r.width) as unknown as string);const vals=caGrFns().filter(f=>f&&f.f).map(fn=>`<span class="s${fn!.i}">f${fn!.i+1} = ${caE(caFmt(fn!.f!(x),{sig:6}))}</span>`);
    tip!.hidden=false;tip!.innerHTML=`<b>x = ${caE(caFmt(x,{sig:6}))}</b>${vals.join("")}`;tip!.style.left=Math.min(r.width-150,Math.max(0,e.clientX-r.left+12))+"px";tip!.style.top=Math.max(0,e.clientY-r.top-10)+"px"});
  const up=()=>{drag=null;svg!.classList.remove("drag")};svg!.addEventListener("pointerup",up);svg!.addEventListener("pointerleave",()=>{R!.querySelector<HTMLInputElement>("[data-grtip]")!.hidden=true;up()});
  try{const ro=new ResizeObserver(()=>caGrDraw());ro.observe(svg!)}catch(e){}}
