function caEdAc(){const R=caRoot();const ta=R?.querySelector<HTMLInputElement>("[data-caed]");const ac=R?.querySelector<HTMLInputElement>("[data-edac]");if(!ta||!ac)return;const s=ta.value,p=ta.selectionStart;const m=s.slice(0,p!).match(/@?[A-Za-z_][A-Za-z0-9_]*$/);if(!m||ta.selectionStart!==ta.selectionEnd){ac.hidden=true;return}const items=caEdAcItems(m[0]);if(!items.length){ac.hidden=true;return}
  CA.edAc={items,pre:m[0],i:0};const line=s.slice(0,p!).split("\n").length-1,col=p!-(s.lastIndexOf("\n",p!-1)+1);const cs=getComputedStyle(ta);const lh=parseFloat(cs.lineHeight)||20;const cw=caEdCharW(ta);
  ac.style.top=(parseFloat(cs.paddingTop)+(line+1)*lh-ta.scrollTop+2)+"px";ac.style.left=Math.max(4,parseFloat(cs.paddingLeft)+(col-m[0].length)*cw-ta.scrollLeft)+"px";
  ac.innerHTML=items.map((it,i)=>`<li role="option" aria-selected="${i===0}" data-aci="${i}"><span class="${it.k}">${caE(it.t)}</span><small>${caE(it.d)}</small></li>`).join("");ac.hidden=false}
function caEdCharW(ta: HTMLInputElement){if(!CA.cw){const s=document.createElement("span");s.style.cssText="position:absolute;visibility:hidden;white-space:pre;font:"+getComputedStyle(ta).font;s.textContent="0".repeat(40);document.body.appendChild(s);CA.cw=s.getBoundingClientRect().width/40;s.remove()}return CA.cw}
function caEdAcPick(i: number){const R=caRoot();const ta=R!.querySelector<HTMLInputElement>("[data-caed]");const a=CA.edAc;if(!a)return;const it=a.items[i];const p=ta!.selectionStart;ta!.value=ta!.value.slice(0,p!-a.pre.length)+it.ins+ta!.value.slice(p!);const np=p!-a.pre.length+it.ins.length;ta!.setSelectionRange(np,np);R!.querySelector<HTMLInputElement>("[data-edac]")!.hidden=true;CA.edAc=null;ta!.focus();caEdPaint()}
