function caPgParse(s: string,base: number){s=String(s||"").trim().replace(/[\s_']/g,"").toLowerCase();if(!s)throw new CaErr("ca_eReq",undefined,caW("value"));let neg=false;if(s[0]==="-"){neg=true;s=s.slice(1)}const pre={16:"0x",2:"0b",8:"0o"}[base];if(pre&&s.startsWith(pre))s=s.slice(2);const dg="0123456789abcdefghijklmnopqrstuvwxyz".slice(0,base);if(!s||[...s].some(c=>!dg.includes(c)))throw new CaErr("ca_eDigit",undefined,String(base));let v=0n;const B=BigInt(base);for(const c of s)v=v*B+BigInt(dg.indexOf(c));return neg?-v:v}
