const CA_FREQ: [string, string][]=[["12","Mensuelle|Monthly|Monatlich|شهري"],["4","Trimestrielle|Quarterly|Vierteljährlich|ربع سنوي"],["2","Semestrielle|Half-yearly|Halbjährlich|نصف سنوي"],["1","Annuelle|Yearly|Jährlich|سنوي"],["52","Hebdomadaire|Weekly|Wöchentlich|أسبوعي"]];
function caAmort(P: number,rAnnual: number,n: number,f: number,kind: string){const i=rAnnual/f;const rows: [string, number, number, number, number][]=[];let bal=Math.round(P*100);const pay=kind==="ann"?(i===0?P/n:P*i/(1-Math.pow(1+i,-n))):null;const payC=pay!==null?Math.round(caRoundMoney(pay)*100):null;const princC=kind==="lin"?Math.round(caRoundMoney(P/n)*100):null;let ti=0;
  for(let k=1;k<=n;k++){const int=Math.round(caRoundMoney(bal/100*i)*100);let prin=kind==="ann"?payC!-int:princC;if(k===n||prin!>bal)prin=bal;const tot=prin!+int;bal-=prin!;ti+=int;rows.push([String(k),(tot/100),(int/100),(prin!/100),(bal/100)])}return {rows,pay:pay!==null?payC!/100:null,ti:ti/100}}
