function caCfPaint(){const R=caRoot();const box=R?.querySelector<HTMLInputElement>("[data-cfres]");if(!box)return;const g=(k: string)=>R!.querySelector<HTMLInputElement>(`[data-cfk="${k}"]`)!.value;const src=g("expr");const vars=caCfVars(src);const vb=R!.querySelector<HTMLInputElement>("[data-cfvars]");CA.cf.vals=CA.cf.vals||{};
  if(!src.trim()){vb!.innerHTML="";box.innerHTML=`<p class="ca-mut">${caE(L4("Saisissez une expression.|Type an expression.|Ausdruck eingeben.|اكتب تعبيرًا."))}</p>`;return}
  if(vars===null){try{caParse(src)}catch(e){box.innerHTML=`<div class="ca-err">${caE(caErrMsg(e))}</div>`}vb!.innerHTML="";return}
  const cur=[...vb!.querySelectorAll<HTMLInputElement>("[data-cfv]")].map(i=>i.dataset.cfv).join(",");if(cur!==vars.join(","))vb!.innerHTML=vars.map(v=>`<label class="ca-fld"><span>${caE(v)}</span><input class="ca-in num" data-cfv="${caE(v)}" dir="ltr" value="${caE(CA.cf.vals![v]??"")}"></label>`).join("");
  try{const loc: Record<string, CaV>={};vars.forEach(v=>{const x=CA.cf.vals![v];if(x===undefined||x==="")throw new CaErr("ca_eReq",undefined,v);loc[v]=caNumIn(x)!});const r=caMkFnN(src)(loc);box.innerHTML=caResHTML({main:[g("name")||CAW.result,caFmt(r),g("note").split(/[;,]/)[0].trim().length<12?g("note").split(/[;,]/)[0].trim():""],formula:src,assume:g("note")?[g("note")]:[]});CA.last={d:CA_T.custom,res:{main:[g("name")||"f",caFmt(r)]}}}catch(e){box.innerHTML=`<div class="ca-err">${caE(caErrMsg(e))}</div>`}}
