onDoc("click",e=>{const R=caRoot();if(!R||!R.contains(tgt(e)))return;const c=(s: string)=>tgt(e).closest<HTMLInputElement>(s);let x: HTMLInputElement | null;const S=caSt();S.formulas=S.formulas||[];
  if(c("[data-cfsave]")){const g=(k: string)=>R.querySelector<HTMLInputElement>(`[data-cfk="${k}"]`)!.value.trim();if(!g("name")||!g("expr")||caCfVars(g("expr"))===null){caToast(caErrMsg(new CaErr("ca_eReq",undefined,L4("Nom et expression valides|Valid name and expression|Name und gültiger Ausdruck|اسم وتعبير صالحان"))));return}let f=S.formulas.find(f=>f.id===CA.cf.sel);if(!f){f={id:"f"+Date.now().toString(36)} as CaFormula;S.formulas.push(f);CA.cf.sel=f.id}Object.assign(f,{name:g("name"),expr:g("expr"),note:g("note")});caSave();R.querySelector<HTMLInputElement>(".ca-pg")!.innerHTML=caCfHTML();caCfPaint();caToast("✓");return}
  if(c("[data-cfnew]")){CA.cf.sel=null;CA.cf.vals={};R.querySelector<HTMLInputElement>(".ca-pg")!.innerHTML=caCfHTML();caCfPaint();R.querySelector<HTMLInputElement>('[data-cfk="name"]')!.focus();return}
  if((x=c("[data-cfopen]"))){CA.cf.sel=x.dataset.cfopen!;CA.cf.vals={};R.querySelector<HTMLInputElement>(".ca-pg")!.innerHTML=caCfHTML();caCfPaint();return}
  if(c("[data-cfdel]")){caConfirm(L4("Supprimer cette formule ?|Delete this formula?|Diese Formel löschen?|حذف هذه الصيغة؟"),()=>{S.formulas=S.formulas!.filter(f=>f.id!==CA.cf.sel);CA.cf.sel=null;caSave();R.querySelector<HTMLInputElement>(".ca-pg")!.innerHTML=caCfHTML();caCfPaint()});return}},true);

