onDoc("change",e=>{const R=caRoot();if(!R||!R.contains(tgt(e)))return;const x=tgt(e);
  if(x.matches("[data-cset]")){const S=caSet();const k=x.dataset.cset;(S as unknown as Record<string, unknown>)[k!]=/^\d+$/.test(x.value)?+x.value:x.value;caSave();R.querySelector<HTMLInputElement>(".ca-pg")!.innerHTML=caSetHTML();R.querySelector<HTMLInputElement>(".ca-hd")!.outerHTML=caHeadHTML();R.querySelector<HTMLInputElement>(`[data-cset="${k}"]`)?.focus();caToast("✓");return}
  if(x.matches("[data-cimp]")){const f=x.files&&x.files[0];if(!f)return;f.text().then(s=>{const j=JSON.parse(s);if(!j||j.remotionCalcData!==1||!j.data)throw new Error("format");const S=caSt();["hist","saved","fav","recent","consts","units","rates","convFav","formulas"].forEach(k=>{if(Array.isArray(j.data[k]))(S as unknown as Record<string, unknown>)[k]=j.data[k]});if(j.data.vars&&typeof j.data.vars==="object")S.vars=j.data.vars;if(j.data.set)S.set=Object.assign({},CA_DEF,j.data.set);if(typeof j.data.editor==="string")S.editor=j.data.editor;caSave(true);caUnitsBuild();caRender(true);caToast(caW("import")+" ✓")}).catch(()=>caToast(L4("Fichier non reconnu|File not recognised|Datei nicht erkannt|ملف غير معروف")))}},true);
onDoc("click",e=>{const R=caRoot();if(!R||!R.contains(tgt(e)))return;const c=(s: string)=>tgt(e).closest<HTMLInputElement>(s);let x: HTMLInputElement | null;
  if(c("[data-cexp]")){caDownload("remotion-calculatrice.json",JSON.stringify({remotionCalcData:1,exported:new Date().toISOString(),data:caSt()},null,1),"application/json");return}
  if(c("[data-creset]")){caConfirm(L4("Effacer réglages, historique, variables, formules et unités personnalisées ?|Erase settings, history, variables, formulas and custom units?|Einstellungen, Verlauf, Variablen, Formeln und Einheiten löschen?|مسح كل البيانات؟"),()=>{try{localStorage.removeItem("remotion-calc")}catch(e){}CA.st=null;caSt();caUnitsBuild();CA.view="home";caRender(true)});return}
  if(c("[data-cuadd]")){const g=(k: string)=>R.querySelector<HTMLInputElement>(`[data-cu="${k}"]`)!.value.trim();try{const f=caNumIn(g("f"));const sym=g("sym");if(!sym||!(f!>0))throw new CaErr("ca_ePos");const cat=g("cat");if(caUnitsOf(cat).some(u=>u.sym===sym))throw new CaErr("ca_eReserved",0,sym);caSt().units.push({id:Date.now().toString(36),cat,sym,name:g("name")||sym,f});caSave();caUnitsBuild();R.querySelector<HTMLInputElement>(".ca-pg")!.innerHTML=caSetHTML();caToast("✓")}catch(err){caToast(caErrMsg(err))}return}
  if((x=c("[data-cudel]"))){caSt().units.splice(+x.dataset.cudel!,1);caSave();caUnitsBuild();R.querySelector<HTMLInputElement>(".ca-pg")!.innerHTML=caSetHTML();return}
  if((x=c("[data-vdel]"))){delete caSt().vars[x.dataset.vdel!];caSave();R.querySelector<HTMLInputElement>(".ca-pg")!.innerHTML=CA_T.library.page!();return}},true);
